cypress_script:
describe('Broken Images Page', () => {
  it('should display the correct title and heading', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.title().should('eq', 'The Internet');
    cy.get('h1').should('have.text', 'Broken Images');
  });
  it('should have the footer visible', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.get('#page-footer').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Broken Images Page', () => {
  test('should display the correct title and heading', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    await expect(page).toHaveTitle('The Internet');
    await expect(page.locator('h1')).toHaveText('Broken Images');
  });
  test('should have the footer visible', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    await expect(page.locator('#page-footer')).toBeVisible();
  });
});
